ALTER TABLE `SRO_SHARD`.`GAMEPLAY_MOB_RATES`
    ADD COLUMN `GUILD_CREATION_COST` BIGINT UNSIGNED NOT NULL DEFAULT 500000 AFTER `MOB_PURSUIT_REFRESH_MS`,
    ADD COLUMN `ACADEMY_CREATION_COST` BIGINT UNSIGNED NOT NULL DEFAULT 100000 AFTER `GUILD_CREATION_COST`,
    ADD COLUMN `ACADEMY_MIN_LEVEL` INT UNSIGNED NOT NULL DEFAULT 60 AFTER `ACADEMY_CREATION_COST`,
    ADD COLUMN `GUILD_WAR_MAX_WAGER` BIGINT UNSIGNED NOT NULL DEFAULT 500000000 AFTER `ACADEMY_MIN_LEVEL`,
    ADD COLUMN `MARKET_LIFETIME_MINUTES` INT UNSIGNED NOT NULL DEFAULT 4320 AFTER `GUILD_WAR_MAX_WAGER`,
    ADD COLUMN `CHARACTER_DELETION_RETENTION_HOURS` INT UNSIGNED NOT NULL DEFAULT 168 AFTER `MARKET_LIFETIME_MINUTES`,
    ADD COLUMN `RECALL_CONFIRMATION_TTL_MS` INT UNSIGNED NOT NULL DEFAULT 60000 AFTER `CHARACTER_DELETION_RETENTION_HOURS`,
    ADD COLUMN `GUILD_ELECTION_DURATION_MINUTES` INT UNSIGNED NOT NULL DEFAULT 10 AFTER `RECALL_CONFIRMATION_TTL_MS`,
    ADD COLUMN `GUILD_MASTER_ABSENCE_DAYS` INT UNSIGNED NOT NULL DEFAULT 45 AFTER `GUILD_ELECTION_DURATION_MINUTES`,
    ADD COLUMN `GUILD_ELECTION_RECENT_MEMBER_DAYS` INT UNSIGNED NOT NULL DEFAULT 15 AFTER `GUILD_MASTER_ABSENCE_DAYS`,
    ADD COLUMN `FRIEND_LIMIT` INT UNSIGNED NOT NULL DEFAULT 20 AFTER `GUILD_ELECTION_RECENT_MEMBER_DAYS`,
    ADD COLUMN `BLOCK_LIMIT` INT UNSIGNED NOT NULL DEFAULT 20 AFTER `FRIEND_LIMIT`,
    ADD COLUMN `MEMO_LIMIT` INT UNSIGNED NOT NULL DEFAULT 20 AFTER `BLOCK_LIMIT`,
    ADD COLUMN `PK_PENALTY_PER_KILL` INT UNSIGNED NOT NULL DEFAULT 10000 AFTER `MEMO_LIMIT`,
    ADD COLUMN `BERSERK_DURATION_PER_POINT_MS` INT UNSIGNED NOT NULL DEFAULT 12000 AFTER `PK_PENALTY_PER_KILL`,
    ADD CONSTRAINT `chk_runtime_economy_policy` CHECK (`GUILD_CREATION_COST` > 0 AND `ACADEMY_CREATION_COST` > 0 AND `ACADEMY_MIN_LEVEL` BETWEEN 1 AND 255 AND `GUILD_WAR_MAX_WAGER` BETWEEN 1 AND 4294967295),
    ADD CONSTRAINT `chk_runtime_lifecycle_policy` CHECK (`MARKET_LIFETIME_MINUTES` > 0 AND `CHARACTER_DELETION_RETENTION_HOURS` > 0 AND `RECALL_CONFIRMATION_TTL_MS` > 0 AND `GUILD_ELECTION_DURATION_MINUTES` > 0 AND `GUILD_MASTER_ABSENCE_DAYS` > 0 AND `GUILD_ELECTION_RECENT_MEMBER_DAYS` > 0),
    ADD CONSTRAINT `chk_runtime_social_pvp_policy` CHECK (`FRIEND_LIMIT` BETWEEN 1 AND 255 AND `BLOCK_LIMIT` BETWEEN 1 AND 255 AND `MEMO_LIMIT` BETWEEN 1 AND 255 AND `PK_PENALTY_PER_KILL` BETWEEN 1 AND 2147483647 AND `BERSERK_DURATION_PER_POINT_MS` > 0);
